/**
 * ============================================================================
 * FESTI'CIVISME — SCRIPT PRINCIPAL & GESTION DU PASS CITOYEN
 * Architecture dynamique multi-éditions (2024 - 2027)
 * ============================================================================
 */

document.addEventListener('DOMContentLoaded', () => {
  /* ==========================================================================
     0. CONFIGURATION ANNUELLE DYNAMIQUE DU FESTIVAL
     Permet de mettre à jour le site chaque année en changeant uniquement cette
     configuration (dates, édition, préfixe des pass).
     ========================================================================== */
  const FESTIVAL_EDITIONS = {
    '2024': {
      year: '2024',
      editionLabel: '1ʳᵉ Édition • 2024',
      datesLabel: 'Nov. 2024 • Yeumbeul Nord',
      targetIso: '2024-11-21T09:00:00Z',
      badgeTitle: 'PASS CITOYEN 2024',
      codePrefix: 'FDC-2024'
    },
    '2025': {
      year: '2025',
      editionLabel: '2ᵉ Édition • 2025',
      datesLabel: 'Nov. 2025 • Yeumbeul Nord',
      targetIso: '2025-11-20T09:00:00Z',
      badgeTitle: 'PASS CITOYEN 2025',
      codePrefix: 'FDC-2025'
    },
    '2026': {
      year: '2026',
      editionLabel: '3ᵉ Édition • 2026',
      datesLabel: '19–21 nov. 2026 à Yeumbeul Nord',
      targetIso: '2026-11-19T09:00:00Z',
      badgeTitle: 'PASS CITOYEN 2026',
      codePrefix: 'FDC-2026'
    },
    '2027': {
      year: '2027',
      editionLabel: '4ᵉ Édition • 2027',
      datesLabel: '18–20 nov. 2027 à Yeumbeul Nord',
      targetIso: '2027-11-18T09:00:00Z',
      badgeTitle: 'PASS CITOYEN 2027',
      codePrefix: 'FDC-2027'
    }
  };

  let currentYear = '2026';

  /* Logo Festi'Civisme encodé en Base64 pour garantir que html2canvas
     fonctionne même lorsque le site est ouvert directement en local (file://) */
  const LOGO_DATA_URI = 'data:image/jpeg;base64,';

  const badgeLogoImg = document.getElementById('badgeLogoImg');
  if (badgeLogoImg && LOGO_DATA_URI.startsWith('data:image/')) {
    badgeLogoImg.src = LOGO_DATA_URI;
  }

  /* ==========================================================================
     1. COMPTE À REBOURS DYNAMIQUE (Cible : 19 Novembre 2026 à 09h00 GMT)
     ========================================================================== */
  const daysEl = document.getElementById('cd-days');
  const hoursEl = document.getElementById('cd-hours');
  const minutesEl = document.getElementById('cd-minutes');
  const secondsEl = document.getElementById('cd-seconds');

  function updateCountdown() {
    const cfg = FESTIVAL_EDITIONS[currentYear] || FESTIVAL_EDITIONS['2026'];
    const targetDate = new Date(cfg.targetIso).getTime();
    const diff = targetDate - Date.now();

    if (diff <= 0) {
      if (daysEl) daysEl.textContent = '00';
      if (hoursEl) hoursEl.textContent = '00';
      if (minutesEl) minutesEl.textContent = '00';
      if (secondsEl) secondsEl.textContent = '00';
      return;
    }

    const days = Math.floor(diff / (1000 * 60 * 60 * 24));
    const hours = Math.floor((diff % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60));
    const minutes = Math.floor((diff % (1000 * 60 * 60)) / (1000 * 60));
    const seconds = Math.floor((diff % (1000 * 60)) / 1000);

    if (daysEl) daysEl.textContent = String(days).padStart(2, '0');
    if (hoursEl) hoursEl.textContent = String(hours).padStart(2, '0');
    if (minutesEl) minutesEl.textContent = String(minutes).padStart(2, '0');
    if (secondsEl) secondsEl.textContent = String(seconds).padStart(2, '0');
  }

  updateCountdown();
  setInterval(updateCountdown, 1000);

  /* Sélecteur d'édition annuelle dans le pied de page */
  const editionSwitcher = document.getElementById('editionSwitcher');
  const dynamicEditionBadge = document.querySelector('[data-dynamic-edition]');
  editionSwitcher?.addEventListener('change', (e) => {
    currentYear = e.target.value || '2026';
    const cfg = FESTIVAL_EDITIONS[currentYear] || FESTIVAL_EDITIONS['2026'];
    if (dynamicEditionBadge) {
      dynamicEditionBadge.textContent = cfg.editionLabel;
    }
    updateCountdown();
  });

  /* ==========================================================================
     2. ANIMATIONS AU DÉFILEMENT, MOT ROTATIF, MACHINE À ÉCRIRE & COMPTEURS
     ========================================================================== */
  const reduceMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  /* N'active l'état initial caché (.reveal) que si JavaScript est chargé
     et que l'utilisateur n'a pas activé prefers-reduced-motion */
  if (!reduceMotion) {
    document.documentElement.classList.add('js-enabled');
  }

  /* 2.1 Apparition au scroll (IntersectionObserver, seuil 0.15, une seule fois) */
  const autoRevealSelectors = [
    '.section-title',
    '.section-desc',
    '.action-card',
    '.prog-row',
    '.partner-logo-card',
    '.story-card'
  ];
  document.querySelectorAll(autoRevealSelectors.join(', ')).forEach((el) => {
    el.classList.add('reveal');
  });

  /* Décalage en cascade de 120 ms pour les groupes (cartes, programme, partenaires) */
  const staggerGroups = [
    { container: '.actions-grid', item: '.action-card' },
    { container: '.programme-table', item: '.prog-row' },
    { container: '.partner-logos-grid', item: '.partner-logo-card' },
    { container: '.metrics-grid', item: '.metric-item' }
  ];

  staggerGroups.forEach(({ container, item }) => {
    const groupEl = document.querySelector(container);
    if (!groupEl) return;
    groupEl.querySelectorAll(item).forEach((el, index) => {
      el.style.setProperty('--reveal-delay', `${index * 120}ms`);
    });
  });

  const revealEls = document.querySelectorAll('.reveal');

  if (!reduceMotion && 'IntersectionObserver' in window) {
    const revealObserver = new IntersectionObserver(
      (entries, obs) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            entry.target.classList.add('is-visible');
            /* Anime une seule fois : on arrête d'observer l'élément */
            obs.unobserve(entry.target);
          }
        });
      },
      { threshold: 0.15 }
    );
    revealEls.forEach((el) => revealObserver.observe(el));
  } else {
    revealEls.forEach((el) => el.classList.add('is-visible'));
  }

  /* 2.2 Mot qui change sous le titre du hero toutes les 2,5 s :
     "Ensemble pour la " + Culture -> Environnement -> Citoyenneté -> Jeunesse
     (la largeur du mot le plus long "Environnement" est réservée par .hero-word-sizer) */
  const heroWordSlot = document.getElementById('heroWordSlot');
  const rotatingWords = ['Culture', 'Environnement', 'Citoyenneté', 'Jeunesse'];
  let currentWordIndex = 0;

  if (heroWordSlot && !reduceMotion) {
    setInterval(() => {
      currentWordIndex = (currentWordIndex + 1) % rotatingWords.length;
      const nextWordText = rotatingWords[currentWordIndex];

      /* L'ancien mot sort vers le haut avec fondu */
      const currentWordEl = heroWordSlot.querySelector('.hero-word-item.is-current');
      if (currentWordEl) {
        currentWordEl.classList.remove('is-current');
        currentWordEl.classList.add('is-exiting');
        setTimeout(() => {
          currentWordEl.remove();
        }, 500);
      }

      /* Le nouveau mot arrive par le bas */
      const nextWordEl = document.createElement('span');
      nextWordEl.className = 'hero-word-item is-entering';
      nextWordEl.textContent = nextWordText;
      heroWordSlot.appendChild(nextWordEl);

      requestAnimationFrame(() => {
        requestAnimationFrame(() => {
          nextWordEl.classList.remove('is-entering');
          nextWordEl.classList.add('is-current');
        });
      });
    }, 2500);
  }

  /* 2.3 Compteurs animés (3e, 18+, 100%, 7) de 0 à leur valeur en 1,5 s (1500 ms) */
  const counters = document.querySelectorAll('[data-count]');
  const animateCount = (el) => {
    const target = parseInt(el.getAttribute('data-count'), 10) || 0;
    if (reduceMotion) {
      el.textContent = String(target);
      return;
    }
    const duration = 1500;
    const start = performance.now();
    const step = (now) => {
      const p = Math.min((now - start) / duration, 1);
      const eased = 1 - Math.pow(1 - p, 3);
      el.textContent = String(Math.round(target * eased));
      if (p < 1) requestAnimationFrame(step);
    };
    requestAnimationFrame(step);
  };

  if (!reduceMotion && 'IntersectionObserver' in window) {
    const countObserver = new IntersectionObserver(
      (entries, obs) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            animateCount(entry.target);
            obs.unobserve(entry.target);
          }
        });
      },
      { threshold: 0.25 }
    );
    counters.forEach((c) => {
      c.textContent = '0';
      countObserver.observe(c);
    });
  } else {
    counters.forEach((c) => {
      c.textContent = c.getAttribute('data-count') || '0';
    });
  }

  /* Barre de progression de lecture */
  const progress = document.getElementById('scrollProgress');
  const updateProgress = () => {
    const max = document.documentElement.scrollHeight - window.innerHeight;
    const ratio = max > 0 ? window.scrollY / max : 0;
    if (progress) progress.style.transform = `scaleX(${ratio})`;
  };
  window.addEventListener('scroll', updateProgress, { passive: true });
  updateProgress();

  /* ==========================================================================
     3. NAVIGATION, GALERIE & PROGRAMME
     ========================================================================== */
  const siteHeader = document.getElementById('siteHeader');
  const mobileMenuToggle = document.getElementById('mobileMenuToggle');
  const mainNav = document.getElementById('mainNav');
  const navLinks = document.querySelectorAll('.nav-link');

  window.addEventListener('scroll', () => {
    siteHeader?.classList.toggle('scrolled', window.scrollY > 16);
  });

  mobileMenuToggle?.addEventListener('click', () => {
    const isOpen = mainNav?.classList.toggle('open');
    mobileMenuToggle.setAttribute('aria-expanded', String(Boolean(isOpen)));
  });

  navLinks.forEach((link) => {
    link.addEventListener('click', () => {
      navLinks.forEach((l) => l.classList.remove('active'));
      link.classList.add('active');
      mainNav?.classList.remove('open');
    });
  });

  /* Filtres de la Galerie & Lightbox */
  const galTabs = document.querySelectorAll('.gal-tab');
  const galItems = document.querySelectorAll('.gallery-item');

  galTabs.forEach((tab) => {
    tab.addEventListener('click', () => {
      galTabs.forEach((t) => t.classList.remove('active'));
      tab.classList.add('active');
      const cat = tab.getAttribute('data-gal');
      galItems.forEach((item) => {
        item.style.display = cat === 'all' || item.getAttribute('data-gal-cat') === cat ? '' : 'none';
      });
    });
  });

  /* Mini-galeries interactives dans les cartes d'actions (Set Setal & Formations) */
  document.querySelectorAll('.action-thumb').forEach((thumb) => {
    thumb.addEventListener('click', () => {
      const targetId = thumb.getAttribute('data-target-img');
      const newSrc = thumb.getAttribute('data-src');
      const newCaption = thumb.getAttribute('data-caption') || '';
      const targetImg = targetId ? document.getElementById(targetId) : null;

      if (targetImg && newSrc) {
        targetImg.src = newSrc;
        const mainWrap = targetImg.closest('[data-lightbox-src]');
        if (mainWrap) {
          mainWrap.setAttribute('data-lightbox-src', newSrc);
          mainWrap.setAttribute('data-lightbox-caption', newCaption);
        }
      }

      const parentStrip = thumb.closest('.action-thumbs');
      parentStrip?.querySelectorAll('.action-thumb').forEach((t) => t.classList.remove('active'));
      thumb.classList.add('active');
    });
  });

  /* Boutons "Voir plus / Voir moins" pour déplier les textes longs */
  document.querySelectorAll('.readmore-btn').forEach((btn) => {
    btn.addEventListener('click', () => {
      const box = btn.previousElementSibling;
      if (!box || !box.classList.contains('readmore-box')) return;
      const isExpanded = btn.getAttribute('aria-expanded') === 'true';
      const labelSpan = btn.querySelector('span');
      if (isExpanded) {
        box.setAttribute('hidden', '');
        btn.setAttribute('aria-expanded', 'false');
        btn.classList.remove('is-open');
        if (labelSpan) labelSpan.textContent = 'Voir plus';
      } else {
        box.removeAttribute('hidden');
        btn.setAttribute('aria-expanded', 'true');
        btn.classList.add('is-open');
        if (labelSpan) labelSpan.textContent = 'Voir moins';
      }
    });
  });

  const lightbox = document.getElementById('lightbox');
  const lightboxImg = document.getElementById('lightboxImg');
  const lightboxCaption = document.getElementById('lightboxCaption');
  const lightboxClose = document.getElementById('lightboxClose');

  document.querySelectorAll('[data-lightbox-src]').forEach((el) => {
    el.addEventListener('click', () => {
      const src = el.getAttribute('data-lightbox-src');
      const cap = el.getAttribute('data-lightbox-caption') || '';
      if (lightboxImg && src) lightboxImg.src = src;
      if (lightboxCaption) lightboxCaption.textContent = cap;
      lightbox?.removeAttribute('hidden');
      lightbox?.setAttribute('aria-hidden', 'false');
    });
  });

  function closeLightbox() {
    lightbox?.setAttribute('hidden', '');
    lightbox?.setAttribute('aria-hidden', 'true');
  }

  lightboxClose?.addEventListener('click', closeLightbox);
  lightbox?.addEventListener('click', (e) => {
    if (e.target === lightbox) closeLightbox();
  });

  /* Filtres par jour du programme */
  const progTabs = document.querySelectorAll('.prog-tab');
  const progRows = document.querySelectorAll('.prog-row');

  progTabs.forEach((tab) => {
    tab.addEventListener('click', () => {
      progTabs.forEach((t) => t.classList.remove('active'));
      tab.classList.add('active');
      const day = tab.getAttribute('data-day');
      progRows.forEach((row) => {
        row.style.display = day === 'all' || row.getAttribute('data-day') === day ? '' : 'none';
      });
    });
  });

  /* Pré-sélection du programme depuis les cartes d'action et le programme */
  const activitySelect = document.getElementById('activitySelect');
  document.querySelectorAll('[data-preselect]').forEach((btn) => {
    btn.addEventListener('click', () => {
      const val = btn.getAttribute('data-preselect');
      if (val && activitySelect) {
        activitySelect.value = val;
        clearFieldError('activitySelect');
      }
    });
  });

  /* ==========================================================================
     4. STOCKAGE DES PASS CITOYENS (localStorage clé "fdc_passes")
     ========================================================================== */
  const STORAGE_KEY = 'fdc_passes';

  /**
   * Récupère la liste des pass enregistrés.
   * TODO: Pour brancher Supabase plus tard en production, remplacer cette
   * fonction par une requête :
   * const { data, error } = await supabase.from('fdc_passes').select('*');
   */
  function getStoredPasses() {
    try {
      const raw = localStorage.getItem(STORAGE_KEY);
      const parsed = raw ? JSON.parse(raw) : [];
      return Array.isArray(parsed) ? parsed : [];
    } catch (err) {
      console.error('Erreur de lecture localStorage:', err);
      return [];
    }
  }

  /**
   * Enregistre un nouveau pass dans localStorage.
   * TODO: Pour brancher Supabase plus tard en production, remplacer cet
   * enregistrement local par :
   * const { data, error } = await supabase.from('fdc_passes').insert([passObj]);
   */
  function savePassToStorage(passObj) {
    const passes = getStoredPasses();
    passes.push(passObj);
    localStorage.setItem(STORAGE_KEY, JSON.stringify(passes));
  }

  /**
   * Normalise et valide un numéro de téléphone sénégalais :
   * Préfixes autorisés : 77, 78, 76, 70, 75 + 7 chiffres (avec ou sans +221 ou 00221)
   * Retourne le numéro formaté "+221 7X XXX XX XX" ou null si invalide.
   */
  function parseSenegalPhone(rawPhone) {
    const digitsOnly = String(rawPhone || '').replace(/[\s.\-()]/g, '');
    const regex = /^(?:(?:\+|00)?221)?(7[05678])(\d{3})(\d{2})(\d{2})$/;
    const match = digitsOnly.match(regex);
    if (!match) return null;
    return `+221 ${match[1]} ${match[2]} ${match[3]} ${match[4]}`;
  }

  /**
   * Génère un numéro de pass unique au format FDC-2026-XXXX (4 chiffres aléatoires,
   * jamais en double parmi les pass existants).
   */
  function generateUniquePassNumber(existingPasses) {
    const cfg = FESTIVAL_EDITIONS[currentYear] || FESTIVAL_EDITIONS['2026'];
    const usedNumbers = new Set(existingPasses.map((p) => p.numero));
    let candidate = '';
    let attempts = 0;

    do {
      const rand4 = Math.floor(1000 + Math.random() * 9000);
      candidate = `${cfg.codePrefix}-${rand4}`;
      attempts++;
    } while (usedNumbers.has(candidate) && attempts < 9000);

    return candidate;
  }

  /* ==========================================================================
     5. VALIDATION DU FORMULAIRE & GÉNÉRATION DU BADGE EN MODALE
     ========================================================================== */
  const civicForm = document.getElementById('civicRegistrationForm');
  const fullNameInput = document.getElementById('fullName');
  const phoneInput = document.getElementById('phone');
  const quartierInput = document.getElementById('quartier');

  function setFieldError(fieldId, message) {
    const inputEl = document.getElementById(fieldId);
    const errEl = document.getElementById(`err-${fieldId}`);
    if (inputEl) inputEl.classList.add('input-invalid');
    if (errEl) errEl.textContent = message;
  }

  function clearFieldError(fieldId) {
    const inputEl = document.getElementById(fieldId);
    const errEl = document.getElementById(`err-${fieldId}`);
    if (inputEl) inputEl.classList.remove('input-invalid');
    if (errEl) errEl.textContent = '';
  }

  ['fullName', 'phone', 'quartier', 'activitySelect'].forEach((id) => {
    const el = document.getElementById(id);
    el?.addEventListener('input', () => clearFieldError(id));
    el?.addEventListener('change', () => clearFieldError(id));
  });

  /* Éléments de la modale du Pass Citoyen */
  const passModal = document.getElementById('passModal');
  const closePassModalBtn = document.getElementById('closePassModalBtn');
  const passStatusBanner = document.getElementById('passStatusBanner');
  const passStatusText = document.getElementById('passStatusText');
  const passModalTitle = document.getElementById('passModalTitle');
  const badgeDatesText = document.getElementById('badgeDatesText');
  const badgeNameEl = document.getElementById('badgeName');
  const badgeQuartierEl = document.getElementById('badgeQuartier');
  const badgeActivityEl = document.getElementById('badgeActivity');
  const badgeCodeEl = document.getElementById('badgeCode');
  const badgeQrContainer = document.getElementById('badgeQrContainer');
  const downloadPassPngBtn = document.getElementById('downloadPassPngBtn');
  const sharePassWaBtn = document.getElementById('sharePassWaBtn');
  const printPassBtn = document.getElementById('printPassBtn');

  let currentPassData = null;

  /**
   * Affiche le badge vertical dans la modale et génère son QR Code.
   */
  function openPassModal(passObj, isExisting) {
    currentPassData = passObj;
    const cfg = FESTIVAL_EDITIONS[currentYear] || FESTIVAL_EDITIONS['2026'];

    if (passModalTitle) passModalTitle.textContent = cfg.badgeTitle;
    if (badgeDatesText) badgeDatesText.textContent = cfg.datesLabel;
    if (badgeNameEl) badgeNameEl.textContent = passObj.nom;
    if (badgeQuartierEl) badgeQuartierEl.textContent = passObj.quartier;
    if (badgeActivityEl) badgeActivityEl.textContent = passObj.programme;
    if (badgeCodeEl) badgeCodeEl.textContent = passObj.numero;

    /* Bandeau d'état : création ou réaffichage d'un pass existant */
    if (passStatusBanner && passStatusText) {
      if (isExisting) {
        passStatusBanner.classList.add('is-existing');
        passStatusText.textContent = 'Ce numéro est déjà inscrit — voici votre Pass Citoyen existant !';
      } else {
        passStatusBanner.classList.remove('is-existing');
        passStatusText.textContent = 'Inscription validée — votre Pass Citoyen 2026 est prêt !';
      }
    }

    /* Génération du QR code via qrcodejs (contient numéro, nom, téléphone, programme) */
    if (badgeQrContainer) {
      badgeQrContainer.innerHTML = '';
      const qrPayload = [
        `PASS:${passObj.numero}`,
        `NOM:${passObj.nom}`,
        `TEL:${passObj.telephone}`,
        `PROG:${passObj.programme}`
      ].join(' | ');

      if (typeof QRCode !== 'undefined') {
        new QRCode(badgeQrContainer, {
          text: qrPayload,
          width: 96,
          height: 96,
          colorDark: '#070d19',
          colorLight: '#ffffff',
          correctLevel: QRCode.CorrectLevel.M
        });
      } else {
        badgeQrContainer.textContent = passObj.numero;
      }
    }

    /* Mise à jour du lien de partage WhatsApp (wa.me) */
    if (sharePassWaBtn) {
      const siteUrl = window.location.href.startsWith('http')
        ? window.location.href.split('#')[0]
        : 'https://facebook.com/profile.php?id=61574910309164';

      const waMessage = [
        `Bonjour ! Voici mon Pass Citoyen pour le Festival du Civisme (Festi'Civisme 2026) :`,
        `• Nom : ${passObj.nom}`,
        `• N° Pass : ${passObj.numero}`,
        `• Programme : ${passObj.programme}`,
        `• Dates : 19-21 nov. 2026 à Yeumbeul Nord`,
        `• Lien : ${siteUrl}`
      ].join('\n');

      sharePassWaBtn.href = `https://wa.me/?text=${encodeURIComponent(waMessage)}`;
    }

    passModal?.removeAttribute('hidden');
    passModal?.setAttribute('aria-hidden', 'false');
    document.body.style.overflow = 'hidden';
  }

  function closePassModal() {
    passModal?.setAttribute('hidden', '');
    passModal?.setAttribute('aria-hidden', 'true');
    document.body.style.overflow = '';
  }

  closePassModalBtn?.addEventListener('click', closePassModal);
  passModal?.addEventListener('click', (e) => {
    if (e.target === passModal) closePassModal();
  });

  /* Soumission du formulaire avec validation complète */
  civicForm?.addEventListener('submit', (e) => {
    e.preventDefault();

    const nomVal = fullNameInput?.value.trim() || '';
    const phoneRaw = phoneInput?.value.trim() || '';
    const quartierVal = quartierInput?.value.trim() || '';
    const progVal = activitySelect?.value.trim() || '';

    let hasError = false;

    if (nomVal.length < 2) {
      setFieldError('fullName', 'Veuillez saisir votre prénom et votre nom complet.');
      hasError = true;
    } else {
      clearFieldError('fullName');
    }

    const formattedPhone = parseSenegalPhone(phoneRaw);
    if (!phoneRaw) {
      setFieldError('phone', 'Veuillez saisir votre numéro de téléphone.');
      hasError = true;
    } else if (!formattedPhone) {
      setFieldError('phone', 'Format invalide. Utilisez un numéro sénégalais (77, 78, 76, 70 ou 75 + 7 chiffres).');
      hasError = true;
    } else {
      clearFieldError('phone');
    }

    if (quartierVal.length < 2) {
      setFieldError('quartier', 'Veuillez indiquer votre quartier ou votre commune.');
      hasError = true;
    } else {
      clearFieldError('quartier');
    }

    if (!progVal) {
      setFieldError('activitySelect', 'Veuillez sélectionner un programme dans la liste.');
      hasError = true;
    } else {
      clearFieldError('activitySelect');
    }

    if (hasError) return;

    /* Vérification dans localStorage si ce numéro de téléphone est déjà inscrit */
    const allPasses = getStoredPasses();
    const existingPass = allPasses.find((p) => p.telephone === formattedPhone);

    if (existingPass) {
      openPassModal(existingPass, true);
      return;
    }

    /* Création et enregistrement d'un nouveau Pass Citoyen */
    const newPass = {
      numero: generateUniquePassNumber(allPasses),
      nom: nomVal,
      telephone: formattedPhone,
      quartier: quartierVal,
      programme: progVal,
      dateCreation: new Date().toISOString()
    };

    savePassToStorage(newPass);
    openPassModal(newPass, false);
    civicForm.reset();
  });

  /* Action 1 : Télécharger le badge en image PNG avec html2canvas */
  downloadPassPngBtn?.addEventListener('click', async () => {
    const badgeCard = document.getElementById('festivalBadgeCard');
    if (!badgeCard || typeof html2canvas === 'undefined') {
      alert('La librairie de capture est en cours de chargement. Veuillez réessayer.');
      return;
    }

    const originalText = downloadPassPngBtn.querySelector('span')?.textContent || 'Télécharger en image';
    const spanEl = downloadPassPngBtn.querySelector('span');
    if (spanEl) spanEl.textContent = 'Génération du PNG...';
    downloadPassPngBtn.disabled = true;

    try {
      const canvas = await html2canvas(badgeCard, {
        scale: 2,
        backgroundColor: '#070d19',
        useCORS: true,
        allowTaint: true,
        logging: false
      });

      const link = document.createElement('a');
      const fileName = currentPassData?.numero
        ? `Pass-Citoyen-${currentPassData.numero}.png`
        : 'Pass-Citoyen-FestiCivisme-2026.png';
      link.download = fileName;
      link.href = canvas.toDataURL('image/png');
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
    } catch (err) {
      console.error('Erreur lors de la génération PNG:', err);
      alert('Impossible de générer l\'image automatiquement. Vous pouvez utiliser le bouton Imprimer.');
    } finally {
      if (spanEl) spanEl.textContent = originalText;
      downloadPassPngBtn.disabled = false;
    }
  });

  /* Action 3 : Imprimer le badge */
  printPassBtn?.addEventListener('click', () => {
    window.print();
  });

  /* ==========================================================================
     6. MODALE DOSSIER PARTENAIRES
     ========================================================================== */
  const modal = document.getElementById('pressKitModal');
  const openBtn1 = document.getElementById('openPressKitBtn');
  const openBtn2 = document.getElementById('openPressKitTop');
  const closeBtn = document.getElementById('closePressKitBtn');

  function openModal() {
    modal?.removeAttribute('hidden');
    modal?.setAttribute('aria-hidden', 'false');
  }

  function closeModal() {
    modal?.setAttribute('hidden', '');
    modal?.setAttribute('aria-hidden', 'true');
  }

  openBtn1?.addEventListener('click', openModal);
  openBtn2?.addEventListener('click', openModal);
  closeBtn?.addEventListener('click', closeModal);
  modal?.addEventListener('click', (e) => {
    if (e.target === modal) closeModal();
  });

  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape') {
      closeModal();
      closeLightbox();
      closePassModal();
    }
  });
});


/* ==========================================================================
   PACK « EFFET WAOUH » (JavaScript natif, aucune librairie)
   1. Intro cinématique (logo + lettres + rideau) — une fois par session
   2. Explosion de confettis aux couleurs du festival quand « Civisme » apparaît
   3. Projecteur lumineux qui suit la souris dans le hero (ordinateur)
   4. Inclinaison 3D + reflet holographique sur l'affiche et les cartes
   5. Boutons magnétiques + onde lumineuse au clic
   ========================================================================== */
(function () {
  const root = document.documentElement;
  const reduceMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  const finePointer = window.matchMedia('(hover: hover) and (pointer: fine)').matches;
  const isMobile = window.innerWidth <= 768;

  if (reduceMotion) {
    root.classList.remove('intro-playing');
    return;
  }

  /* ---------- 2. Confettis (canvas, ~2,5 s puis suppression) ---------- */
  function launchConfetti() {
    const target = document.querySelector('.hero-word-civisme');
    if (!target) return;
    const rect = target.getBoundingClientRect();
    if (rect.bottom < 0 || rect.top > window.innerHeight) return; // hors écran : inutile

    const canvas = document.createElement('canvas');
    canvas.className = 'fc-confetti-canvas';
    document.body.appendChild(canvas);
    const ctx = canvas.getContext('2d');
    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    canvas.width = window.innerWidth * dpr;
    canvas.height = window.innerHeight * dpr;
    ctx.scale(dpr, dpr);

    const originX = rect.left + rect.width / 2;
    const originY = rect.top + rect.height / 2;
    const colors = ['#4ea832', '#6ee755', '#38bdf8', '#ffffff', '#facc15', '#ecfdf5'];
    const count = isMobile ? 70 : 150;
    const pieces = [];

    for (let i = 0; i < count; i++) {
      const angle = Math.random() * Math.PI * 2;
      const speed = 4 + Math.random() * 9;
      pieces.push({
        x: originX,
        y: originY,
        vx: Math.cos(angle) * speed,
        vy: Math.sin(angle) * speed - 4,
        size: 4 + Math.random() * 6,
        rot: Math.random() * Math.PI,
        vr: (Math.random() - 0.5) * 0.3,
        color: colors[(Math.random() * colors.length) | 0],
        round: Math.random() < 0.35
      });
    }

    const start = performance.now();
    const duration = 2600;

    function frame(now) {
      const t = now - start;
      ctx.clearRect(0, 0, window.innerWidth, window.innerHeight);
      ctx.globalAlpha = Math.max(0, 1 - t / duration);
      pieces.forEach((p) => {
        p.vy += 0.22;      // gravité
        p.vx *= 0.985;     // résistance de l'air
        p.vy *= 0.985;
        p.x += p.vx;
        p.y += p.vy;
        p.rot += p.vr;
        ctx.save();
        ctx.translate(p.x, p.y);
        ctx.rotate(p.rot);
        ctx.fillStyle = p.color;
        if (p.round) {
          ctx.beginPath();
          ctx.arc(0, 0, p.size / 2, 0, Math.PI * 2);
          ctx.fill();
        } else {
          ctx.fillRect(-p.size / 2, -p.size / 4, p.size, p.size / 2);
        }
        ctx.restore();
      });
      if (t < duration) requestAnimationFrame(frame);
      else canvas.remove();
    }
    requestAnimationFrame(frame);
  }

  /* Le mot « Civisme » atterrit ~1 s après le démarrage des animations du hero */
  function startHeroShow() {
    setTimeout(launchConfetti, 1000);
  }

  /* ---------- 1. Intro cinématique ---------- */
  if (root.classList.contains('intro-playing')) {
    try { sessionStorage.setItem('fc-intro-vue', '1'); } catch (e) {}

    const intro = document.createElement('div');
    intro.className = 'fc-intro';
    intro.setAttribute('aria-hidden', 'true');

    /* Titre « Festi'Civisme » lettre par lettre (« Civisme » en vert) */
    const word = "Festi'Civisme";
    const letters = word.split('').map((ch, i) =>
      `<span style="--i:${i}" class="${i >= 6 ? 'is-green' : ''}">${ch}</span>`
    ).join('');

    intro.innerHTML = `
      <div class="fc-intro-panel top"></div>
      <div class="fc-intro-panel bottom"></div>
      <div class="fc-intro-center">
        <div class="fc-intro-logo-wrap"><img src="logo.jpeg" alt="" class="fc-intro-logo" /></div>
        <div class="fc-intro-title">${letters}</div>
        <div class="fc-intro-sub">3ᵉ Édition • 2026</div>
        <div class="fc-intro-bar"></div>
      </div>`;
    document.body.appendChild(intro);

    /* Ouverture du rideau à 1,8 s puis lancement du hero */
    setTimeout(() => {
      intro.classList.add('is-leaving');
      root.classList.remove('intro-playing');
      startHeroShow();
      setTimeout(() => intro.remove(), 1000);
    }, 1800);
  } else {
    startHeroShow();
  }

  /* Les effets suivants ne concernent que les écrans avec souris */
  if (!finePointer) return;

  /* ---------- 3. Projecteur qui suit la souris ---------- */
  const hero = document.querySelector('.hero');
  if (hero) {
    const spot = document.createElement('div');
    spot.className = 'hero-spotlight';
    spot.setAttribute('aria-hidden', 'true');
    hero.prepend(spot);
    let raf = null;
    hero.addEventListener('mousemove', (e) => {
      const r = hero.getBoundingClientRect();
      const x = e.clientX - r.left;
      const y = e.clientY - r.top;
      if (raf) cancelAnimationFrame(raf);
      raf = requestAnimationFrame(() => {
        spot.style.transform = `translate(${x}px, ${y}px)`;
      });
    });
  }

  /* ---------- 4. Inclinaison 3D + reflet holographique ---------- */
  function addTilt(container, moving, maxDeg) {
    if (!container || !moving) return;
    container.classList.add('fc-tilt');
    const glare = document.createElement('span');
    glare.className = 'fc-tilt-glare';
    container.appendChild(glare);

    container.addEventListener('mousemove', (e) => {
      const r = container.getBoundingClientRect();
      const px = (e.clientX - r.left) / r.width;   // 0 → 1
      const py = (e.clientY - r.top) / r.height;
      const rx = (0.5 - py) * maxDeg * 2;
      const ry = (px - 0.5) * maxDeg * 2;
      moving.style.transition = 'transform 0.12s ease-out';
      moving.style.transform = `perspective(900px) rotateX(${rx}deg) rotateY(${ry}deg) scale(1.02)`;
      glare.style.setProperty('--gx', `${px * 100}%`);
      glare.style.setProperty('--gy', `${py * 100}%`);
    });

    container.addEventListener('mouseleave', () => {
      moving.style.transition = 'transform 0.6s cubic-bezier(0.34, 1.56, 0.64, 1)';
      moving.style.transform = '';
    });
  }

  const poster = document.querySelector('.poster-frame');
  addTilt(poster, poster && poster.querySelector('.poster-img'), 9);
  document.querySelectorAll('.action-card').forEach((card) => addTilt(card, card, 6));

  /* ---------- 5. Boutons magnétiques + onde au clic ---------- */
  document.querySelectorAll('.hero-actions .btn, .nav-cta .btn').forEach((btn) => {
    btn.classList.add('fc-magnetic');
    btn.addEventListener('mousemove', (e) => {
      const r = btn.getBoundingClientRect();
      const dx = e.clientX - (r.left + r.width / 2);
      const dy = e.clientY - (r.top + r.height / 2);
      btn.style.transform = `translate(${dx * 0.25}px, ${dy * 0.35}px)`;
    });
    btn.addEventListener('mouseleave', () => {
      btn.style.transform = '';
    });
  });

  document.querySelectorAll('.btn-primary').forEach((btn) => {
    btn.addEventListener('click', (e) => {
      const r = btn.getBoundingClientRect();
      const ripple = document.createElement('span');
      ripple.className = 'fc-ripple';
      ripple.style.left = `${e.clientX - r.left}px`;
      ripple.style.top = `${e.clientY - r.top}px`;
      btn.appendChild(ripple);
      setTimeout(() => ripple.remove(), 700);
    });
  });
})();
